<script setup>
import {computed,nextTick,onMounted,ref} from 'vue';
import Icon from '../Icon.vue';
import Modal from '../Modal.vue';
import {api,money,dateTime,labels,stages,notify,localDate} from '../../lib';
const orders=ref([]),filter=ref('active'),selected=ref(null),loading=ref(true),busy=ref(false),error=ref(''),detailError=ref(''),historyDate=ref(''),receipt=ref(null);
const counts=computed(()=>Object.fromEntries(stages.map(s=>[s,orders.value.filter(x=>x.status===s).length])));
const filtered=computed(()=>orders.value.filter(x=>(filter.value==='active'?x.status!=='completed':filter.value==='history'?x.status==='completed':x.status===filter.value)&&(filter.value!=='history'||!historyDate.value||localDate(new Date(x.completed_at))===historyDate.value)));
async function load(){loading.value=true;error.value='';try{orders.value=await api('/admin/orders');if(selected.value)selected.value=orders.value.find(x=>x.id===selected.value.id)||null;}catch(e){error.value=e.message;}finally{loading.value=false;}}
onMounted(load);
async function update(body){busy.value=true;detailError.value='';try{const updated=await api(`/admin/orders/${selected.value.id}`,{method:'PATCH',body:{...body,version:selected.value.version}});orders.value=orders.value.map(x=>x.id===updated.id?updated:x);selected.value=updated;notify('Pesanan berhasil diperbarui.');}catch(e){detailError.value=e.message;if(e.status===409)await load();}finally{busy.value=false;}}
async function print(){receipt.value=selected.value;await nextTick();window.addEventListener('afterprint',()=>receipt.value=null,{once:true});window.print();}
</script>
<template><div class="metric-grid"><div v-for="stage in stages" :key="stage" class="metric"><span>{{labels[stage]}}</span><strong>{{counts[stage]||0}}<small>pesanan</small></strong></div></div><div class="admin-toolbar"><div class="filter-tabs"><button v-for="item in [{id:'active',name:'Pesanan aktif'},{id:'received',name:'Baru masuk'},{id:'history',name:'Riwayat selesai'}]" :key="item.id" :class="{active:filter===item.id}" @click="filter=item.id">{{item.name}}</button></div><div class="toolbar-actions"><input v-if="filter==='history'" v-model="historyDate" type="date" aria-label="Tanggal pesanan selesai"/><button class="button secondary" :disabled="loading" @click="load"><Icon name="RefreshCw" :size="16" :class="{spin:loading}"/>Refresh</button></div></div><div v-if="error" class="alert error" role="alert">{{error}}</div><div v-if="loading" class="skeleton table-skeleton"></div><div v-else-if="!filtered.length" class="panel empty-state"><Icon name="ClipboardList" :size="38"/><h2>{{filter==='history'?'Belum ada riwayat pesanan':'Belum ada pesanan masuk'}}</h2><p>Tekan Refresh untuk mengambil pesanan terbaru.</p></div><div v-else class="table-wrap"><table><thead><tr><th>Pesanan</th><th>Pelanggan</th><th>Tipe</th><th>Total</th><th>Pembayaran</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="order in filtered" :key="order.id"><td><strong class="order-code">{{order.code}}</strong><small>{{dateTime(order.created_at)}}</small></td><td><strong>{{order.customer_name}}</strong><small>{{order.items.reduce((n,x)=>n+x.quantity,0)}} item</small></td><td>{{order.order_type==='dine_in'?`Meja ${order.table_number}`:'Takeaway'}}</td><td class="nowrap">{{money(order.total)}}</td><td><span :class="['badge',order.payment_status==='paid'?'success':'warning']">{{order.payment_status==='paid'?'Lunas':'Belum dibayar'}}</span></td><td><span :class="['badge',order.status==='completed'?'success':'neutral']">{{labels[order.status]}}</span></td><td><button class="text-button" @click="selected=order;detailError=''">Detail <Icon name="ArrowUpRight" :size="14"/></button></td></tr></tbody></table></div><p class="table-caption">Pesanan diperbarui saat tombol Refresh ditekan.</p>
<Modal v-if="selected" title="Detail pesanan" wide @close="selected=null"><div class="order-heading"><div><h3>{{selected.code}}</h3><p>{{dateTime(selected.created_at)}}</p></div><span class="badge neutral">{{labels[selected.status]}}</span></div><div class="detail-meta"><div><small>PELANGGAN</small><strong>{{selected.customer_name}}</strong><span>{{selected.whatsapp}}</span></div><div><small>TIPE PESANAN</small><strong>{{selected.order_type==='dine_in'?`Dine-in · Meja ${selected.table_number}`:'Takeaway'}}</strong><span>{{selected.payment_method==='qris'?'QRIS':'Transfer bank'}}</span></div></div><div class="summary-line" v-for="item in selected.items" :key="item.menu_id"><div><strong>{{item.quantity}}× {{item.name}}</strong><p v-if="item.note" class="kitchen-note"><Icon name="Info" :size="14"/>{{item.note}}</p></div><span>{{money(item.price*item.quantity)}}</span></div><div class="summary-total"><span>Total</span><strong>{{money(selected.total)}}</strong></div><div class="payment-verification"><span :class="['badge',selected.payment_status==='paid'?'success':'warning']">{{selected.payment_status==='paid'?'Pembayaran lunas':'Belum dibayar'}}</span><p v-if="selected.payment_status!=='paid'">Periksa dana masuk melalui aplikasi bank atau QRIS sebelum mengonfirmasi.</p><button v-if="selected.payment_status!=='paid'" class="button secondary" :disabled="busy" @click="update({payment_status:'paid'})"><Icon name="CheckCircle2" :size="17"/>Konfirmasi lunas</button></div><p v-if="detailError" class="alert error" role="alert">{{detailError}}</p><div class="modal-actions"><button class="button secondary" @click="print"><Icon name="Printer" :size="17"/>Cetak struk</button><button v-if="selected.status!=='completed'" class="button primary" :disabled="busy||selected.payment_status!=='paid'" @click="update({status:stages[stages.indexOf(selected.status)+1]})">Tandai {{labels[stages[stages.indexOf(selected.status)+1]]}}<Icon name="ArrowRight" :size="17"/></button></div></Modal>
<div v-if="receipt" class="print-receipt"><h2>Taman Teras Cafe</h2><p>{{receipt.code}}<br/>{{dateTime(receipt.created_at)}}</p><p>{{receipt.customer_name}}<br/>{{receipt.order_type==='dine_in'?`Meja ${receipt.table_number}`:'Takeaway'}}</p><hr/><div v-for="item in receipt.items" :key="item.menu_id" class="summary-line"><span>{{item.quantity}}× {{item.name}}<small v-if="item.note">{{item.note}}</small></span><span>{{money(item.price*item.quantity)}}</span></div><hr/><div class="summary-line"><strong>Total</strong><strong>{{money(receipt.total)}}</strong></div><p>{{receipt.payment_method.toUpperCase()}} · {{receipt.payment_status==='paid'?'LUNAS':'BELUM DIBAYAR'}}</p><p>Terima kasih sudah singgah!</p></div>
</template>
